/* Public system entry point. Kept at its existing URL for older page links. */
(async function(){
'use strict';
const target=document.getElementById('d2Content');
if(!target)return;
document.getElementById('d2Gate')?.remove();
target.hidden=false;
target.setAttribute('aria-busy','true');
try{
 const [app,study]=await Promise.all([
  import('./dh20.js?v=20261115-public1'),
  fetch('dh20-study.json?v=20261115-public1').then(r=>{if(!r.ok)throw Error('Study unavailable');return r.json();})
 ]);
 await app.mount(target,study);
}catch(error){
 target.replaceChildren();
 const title=document.createElement('h1'),message=document.createElement('p'),retry=document.createElement('button');
 title.textContent='DH2.0 — The Thermostat';
 message.textContent='System research is temporarily unavailable. Please try again.';
 message.setAttribute('role','alert');
 retry.type='button';retry.textContent='Try again';retry.onclick=()=>location.reload();
 target.append(title,message,retry);
}finally{target.removeAttribute('aria-busy');}
})();

const finite=v=>typeof v==='number'&&Number.isFinite(v);
const time=v=>Date.parse(v),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const day=v=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v));
const signed=v=>finite(v)?(v>0?'+':'')+v:'—';
function view(g,team){const side=g.home===team?'home':g.away===team?'away':null;if(!side)return null;const other=side==='home'?'away':'home',pf=g[side+'Score'],pa=g[other+'Score'],line=finite(g.homeSpread)?g.homeSpread*(side==='home'?1:-1):null;return {g,side,opponent:g[other],pf,pa,line,ats:finite(pf)&&finite(pa)&&finite(line)?pf-pa+line:null,opponentRank:g[other+'Rank']};}
function miles(a,b){if(![a?.latitude,a?.longitude,b?.latitude,b?.longitude].every(finite))return null;const [la,lo,lb,lp]=[a.latitude,a.longitude,b.latitude,b.longitude].map(v=>v*Math.PI/180);return 3958.8*2*Math.asin(Math.min(1,Math.sqrt(Math.sin((lb-la)/2)**2+Math.cos(la)*Math.cos(lb)*Math.sin((lp-lo)/2)**2)));}
const contexts=new WeakMap();
function context(history,team,date){let index=contexts.get(history);if(!index){const byTeam=new Map();for(const g of history)for(const t of [g.home,g.away]){if(!byTeam.has(t))byTeam.set(t,[]);byTeam.get(t).push({g,t:time(g.date)});}for(const rows of byTeam.values())rows.sort((a,b)=>a.t-b.t);index={byTeam,cache:new Map()};contexts.set(history,index);}const key=team+'|'+date;if(index.cache.has(key))return index.cache.get(key);const cutoff=time(date),rows=(index.byTeam.get(team)||[]).filter(p=>p.t<cutoff);const result={prior:rows.filter(p=>p.g.done).map(p=>view(p.g,team)),latest:rows.filter(p=>!/CANCEL/.test(p.g.status||'')).at(-1)?.g};index.cache.set(key,result);return result;}
export function qualification(id,g,team,teams,history){if(!g?.fbs||g.timeValid===false||/POSTPON|CANCEL|SUSPEND/.test(g.status||''))return null;const v=view(g,team);if(!v)return null;const a=context(history,team,g.date),b=context(history,v.opponent,g.date),own=a.prior,opp=b.prior,last=own.at(-1),otherLast=opp.at(-1);const needed=['regional','momentum'].includes(id)?a.latest:b.latest;if(!needed?.done)return null;let reason='',evidence=[];
if(id==='regional'){if(g.neutral||v.side!=='away'||!g.venueId||String(g.venueId)!==String(teams[g.home]?.venueId))return null;const distance=miles(teams[team],teams[g.home]);if(!finite(distance)||distance>=500||own.length<3||own.slice(-3).some(p=>!finite(p.ats)||p.ats>=0))return null;reason=`Three straight non-covers, followed by a ${Math.round(distance)}-mile road trip.`;evidence=own.slice(-3).map(p=>({game:p.g.id,opponent:p.opponent,text:`${signed(p.line)} · missed the spread by ${Math.abs(p.ats).toFixed(1).replace('.0','')}`}));}
else if(id==='road40'){if(g.neutral||v.side!=='away'||!finite(v.line)||v.line<=0||!otherLast||!finite(otherLast.pa)||otherLast.pa<40)return null;reason=`Getting points on the road against a team that just allowed ${otherLast.pa}.`;evidence=[{game:otherLast.g.id,opponent:otherLast.opponent,text:`Opponent's last game: ${otherLast.pf}–${otherLast.pa}.`}];}
else if(id==='momentum'){if(own.length<3||own.slice(-3).some(p=>!finite(p.ats)||p.ats<=0)||!last||last.side!=='away'||last.g.neutral||last.pf<=last.pa)return null;reason='Three straight covers. Its most recent game was an outright road win.';evidence=own.slice(-3).map(p=>({game:p.g.id,opponent:p.opponent,text:`${signed(p.line)} · covered by ${p.ats.toFixed(1).replace('.0','')}`}));}
else if(id==='spotlight'){if(!otherLast||!finite(otherLast.pf)||!finite(otherLast.pa)||!finite(otherLast.opponentRank)||otherLast.opponentRank>10||otherLast.opponentRank<1||otherLast.pf<=otherLast.pa)return null;reason=`Its opponent just beat a team ranked No. ${otherLast.opponentRank}.`;evidence=[{game:otherLast.g.id,opponent:otherLast.opponent,text:`Opponent won ${otherLast.pf}–${otherLast.pa} against No. ${otherLast.opponentRank}.`}];}
else return null;
return {system:id,g,team,opponent:v.opponent,line:v.line,reason,evidence,key:g.id+':'+team+':'+id};}
export function freshData(data,now=Date.now()){const age=now-time(data?.generatedAt);return data?.status==='ready'&&finite(age)&&age>=0&&age<30*3600000;}
export function grade(g,team,line){const v=view(g,team);if(!g?.done||/POSTPON|CANCEL|SUSPEND/.test(g.status||'')||!v||!finite(v.pf)||!finite(v.pa)||!finite(line))return null;const n=v.pf-v.pa+line;return n>0?'W':n<0?'L':'P';}
export function record(rows){let w=0,l=0,p=0,sw=0,sl=0,dw=0,dl=0;for(const r of rows){if(!['W','L','P'].includes(r.ats))continue;if(r.ats==='W')w++;else if(r.ats==='L')l++;else p++;if(finite(r.pf)&&finite(r.pa)){if(r.pf>r.pa)sw++;else sl++;if(r.line>0){if(r.pf>r.pa)dw++;else dl++;}}}return {w,l,p,pct:w+l?100*w/(w+l):null,sw,sl,dw,dl};}
export function tracked(study,snapshots,games){const byId=new Map(games.map(g=>[g.id,g])),seen=new Set(),out=[];for(const s of snapshots||[]){const capture=time(s.capturedAt),kick=time(s.kickoff),quote=time(s.quote?.retrievedAt);if(!s.game||!s.teams||!s.pending||![capture,kick,quote].every(finite)||capture<time(study.frozenAt)||kick<time(study.trackedFrom)||capture>=kick||quote>capture||capture-quote>30*3600000||!finite(s.quote?.homeSpread))continue;const frozen={...s.game,homeSpread:s.quote.homeSpread},teams={[frozen.home]:s.teams.home,[frozen.away]:s.teams.away},history=[...new Map([...(s.recent?.home||[]),...(s.recent?.away||[]),...(s.pending.home||[]),...(s.pending.away||[])].map(g=>[g.id,g])).values()];for(const system of study.systems)for(const team of [frozen.home,frozen.away]){const q=qualification(system.id,frozen,team,teams,history);if(!q||seen.has(q.key))continue;seen.add(q.key);const actual=byId.get(frozen.id)||frozen,v=view(actual,team);out.push({...q,g:actual,ats:grade(actual,team,q.line),pf:v?.pf,pa:v?.pa,capturedAt:s.capturedAt,quote:s.quote});}}return out;}
const recLabel=r=>r.w+'–'+r.l+(r.p?'–'+r.p:''),percent=r=>r?.pct===null||r?.pct===undefined?'—':r.pct.toFixed(1)+'%';
export async function mount(root,study){
let data=null,archive={snapshots:[]},feed=[],system='all',lens='2026',scope='upcoming',selected=null,selectedDay=null,scene=null,dead=false,items=[],current={},fresh=false,exportRows=[];
const name=t=>data?.teams?.[t]?.name||study.teams[t]?.name||t,abbr=t=>data?.teams?.[t]?.abbr||study.teams[t]?.abbr||name(t),logo=(t,size=32)=>`<img src="assets/logos-small/${encodeURIComponent(t)}.webp" alt="${esc(name(t))} logo" width="${size}" height="${size}" loading="lazy" onerror="this.hidden=true">`,sys=id=>study.systems.find(s=>s.id===id),clock=d=>new Date(d).toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})+' ET';
const historical={};for(const s of study.systems)historical[s.id]=record(s.ledger.filter(r=>r.year<study.season));
root.innerHTML=`<div class="d2-titlebar"><div><div class="d2-eyebrow">SYSTEM RESEARCH <span>///</span></div><h1 tabindex="-1">DH<span>2.0</span><small>THE THERMOSTAT</small></h1></div></div><div class="d2-toolbar"><div class="d2-segments" aria-label="Game scope"><button data-scope="week" aria-label="This week" aria-pressed="true">Week</button><button data-scope="upcoming" aria-label="Upcoming games" aria-pressed="false">Next</button><button data-scope="results" aria-pressed="false">Results</button></div><label class="d2-lens"><span class="d2-lens-label">Heat measured by</span><select id="d2Lens"><option value="2026">2026 history</option><option value="prior">2023–25 history</option><option value="tracked">Since launch</option></select></label></div><p id="d2Status" class="d2-banner" role="status">Loading verified situations…</p><div class="d2-layout"><aside class="d2-system-rail" aria-label="System filters"><div class="d2-rail-title"><h2>System radar</h2><span>04 SYSTEMS</span></div><div id="d2SystemButtons" style="display:contents"></div><p class="d2-rail-note">Heat = the selected system's past cover rate. It is not this game's win probability.</p></aside><section class="d2-center" aria-labelledby="d2SceneTitle"><div class="d2-scene-head"><div><h2 id="d2SceneTitle">The Thermostat</h2><p id="d2Count">Finding qualifying games…</p></div><span>3D / INTERACTIVE</span></div><div id="d2Scene" class="d2-scene d2-active-scene" role="group" aria-label="Qualifying game Thermostat"><canvas aria-hidden="true"></canvas><span class="d2-axis-title">HISTORICAL COVER %</span><div class="d2-axis d2-axis-left" aria-hidden="true"><span>100</span><span>75</span><span>50</span><span>25</span><span>0</span></div><svg id="d2Leaders" class="d2-leaders" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"></svg><div id="d2Markers" class="d2-markers"></div><div id="d2StageEmpty" class="d2-stage-empty" hidden></div><div id="d2Readout" class="d2-live-readout"><strong>—</strong><small>system history</small></div><div class="d2-stage-caption">DRAG TO ROTATE <span aria-hidden="true">↔</span></div></div><div class="d2-orbit-controls" aria-label="Thermostat view"><button data-orbit="left" aria-label="Rotate Thermostat left">↶</button><button data-orbit="reset">Reset view</button><button data-orbit="right" aria-label="Rotate Thermostat right">↷</button></div><div id="d2Timeline" class="d2-timeline" aria-label="Select a game date"></div><details class="d2-all-picks"><summary id="d2AllTitle">All qualifying teams</summary><div id="d2AllPicks"></div></details><p class="d2-chart-note">Tap a team to inspect its system. Switch the history window to compare the hot streak with earlier seasons. Every system shown is a research candidate.</p></section><aside id="d2Detail" class="d2-detail" aria-label="Selected system play"></aside></div><section class="d2-ledger"><div class="d2-ledger-head"><h2>Every qualifier. Every result.</h2><button id="d2Export">Export selected system CSV ↗</button></div><p id="d2LedgerNote"></p><div class="d2-table-wrap"><table class="d2-table"><thead><tr><th scope="col">Game</th><th scope="col">System</th><th scope="col">Spread</th><th scope="col">Result</th><th scope="col">Record type</th></tr></thead><tbody id="d2LedgerRows"></tbody></table></div></section>`;
scene=globalThis.DH20Scene?.mount(root.querySelector('#d2Scene'),{level:.1});root.querySelectorAll('[data-orbit]').forEach(b=>b.onclick=()=>scene?.rotate(b.dataset.orbit));
function games(){const live=new Map(feed.map(g=>[g.id,g]));return (data?.games||[]).map(g=>{const l=live.get(g.id);return l&&!(g.done&&!l.done)?{...g,date:l.date||g.date,done:l.done,status:l.status,homeScore:l.homeScore,awayScore:l.awayScore,live:l.state==='in',scoreDelayed:globalThis.LiveScores?.stale,detail:l.detail}:g;});}
function compute(){const began=performance.now();const now=Date.now(),age=now-time(data?.generatedAt);fresh=freshData(data,now);const gs=games(),sourceTeams=data?.teams||{};items=[];for(const g of gs)for(const s of study.systems)for(const t of [g.home,g.away]){const q=qualification(s.id,g,t,sourceTeams,gs);if(q)items.push(q);}const issued=tracked(study,archive.snapshots,gs);for(const s of study.systems){const measured=items.filter(q=>q.system===s.id).map(q=>{const v=view(q.g,q.team);return {ats:grade(q.g,q.team,q.line),pf:v.pf,pa:v.pa,line:q.line};});current[s.id]={season:data?.games?.length?record(measured):record(s.ledger.filter(r=>r.year===study.season)),prior:historical[s.id],tracked:record(issued.filter(q=>q.system===s.id)),issued:issued.filter(q=>q.system===s.id)};}if(!selectedDay)selectedDay=day(now);root.dataset.computeMs=(performance.now()-began).toFixed(1);}
const heat=q=>current[q.system]?.[lens==='2026'?'season':lens]?.pct??null;
function state(q){if(q.g.done)return 'FINAL · '+({W:'COVERED',L:'MISSED',P:'PUSH'}[grade(q.g,q.team,q.line)]||'UNGRADED');if(q.g.live)return q.g.scoreDelayed?'LIVE · SCORES DELAYED':'LIVE · UNGRADED';if(time(q.g.date)<=Date.now())return 'STARTED · UNGRADED';return 'PREGAME';}
function viewItems(){const today=day(Date.now()),start=new Date(today+'T12:00Z'),dow=(start.getUTCDay()+6)%7;start.setUTCDate(start.getUTCDate()-dow);const monday=start.toISOString().slice(0,10),end=new Date(start);end.setUTCDate(end.getUTCDate()+6);const sunday=end.toISOString().slice(0,10);return items.filter(q=>{if(system!=='all'&&q.system!==system)return false;if(scope==='results')return q.g.done;if(!fresh)return false;if(scope==='upcoming')return !q.g.done&&time(q.g.date)>Date.now();const d=day(q.g.date);return d>=monday&&d<=sunday;});}
function render(focus=false){if(dead)return;root.querySelectorAll('[data-scope]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scope===scope)));root.querySelector('#d2SystemButtons').innerHTML=study.systems.map(s=>{const r=current[s.id]?.[lens==='2026'?'season':lens]||historical[s.id];return `<button class="d2-system" data-system="${s.id}" data-hot="${r.pct>=80}" aria-pressed="${system===s.id}"><b>${esc(s.name)}</b><strong>${percent(r)}</strong><small>${recLabel(r)} ATS · ${lens==='2026'?'2026':lens==='prior'?'2023–25':'since launch'}<br>${lens==='tracked'?'No backfilled research wins':'Earlier: '+recLabel(historical[s.id])+' · '+percent(historical[s.id])}</small></button>`;}).join('');
const status=root.querySelector('#d2Status');status.innerHTML=!fresh?'<strong>Fresh qualifiers unavailable.</strong> Historical evidence remains available; new selections need a fresh data check.':'<strong>Research preview.</strong> Historical rates; picks tracked since launch stay separate.';
const scopeRows=viewItems(),dates=[...new Set(scopeRows.map(q=>day(q.g.date)))].sort();if(dates.length&&!dates.includes(selectedDay))selectedDay=dates.find(d=>d>=day(Date.now()))||dates.at(-1);root.querySelector('#d2Timeline').innerHTML=dates.map(d=>`<button data-date="${d}" aria-pressed="${d===selectedDay}"><span>${d===day(Date.now())?'TODAY':new Date(d+'T12:00Z').toLocaleDateString('en-US',{weekday:'short',timeZone:'America/New_York'}).toUpperCase()}</span><b>${new Date(d+'T12:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'America/New_York'})}</b><small>${new Set(scopeRows.filter(q=>day(q.g.date)===d).map(q=>q.g.id+q.team)).size} teams</small></button>`).join('');
let rows=scopeRows.filter(q=>day(q.g.date)===selectedDay);rows.sort((a,b)=>(heat(b)??-1)-(heat(a)??-1)||time(a.g.date)-time(b.g.date));const groups=new Map();for(const q of rows){const key=q.g.id+':'+q.team;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(q);}const choices=[...groups.values()].map(a=>a.find(q=>q.key===selected)||a[0]);if(!rows.some(q=>q.key===selected))selected=choices[0]?.key||null;const active=rows.find(q=>q.key===selected)||null;root.querySelector('#d2Count').textContent=`${choices.length} qualifying team${choices.length===1?'':'s'}${choices.length?' · '+(selectedDay===day(Date.now())?'today':selectedDay):''}`;
const smallView=matchMedia('(max-width:700px)').matches;const markers=choices.slice(0,smallView?4:8);if(active&&!markers.some(q=>q.key===active.key)){markers.pop();markers.push(active);}const used=[[],[]],leaders=[];const markup=markers.map((q,i)=>{const h=heat(q),col=i%2,y=h===null?88:100-h;let pos=Math.max(8,Math.min(88,y));for(const p of used[col])if(Math.abs(p-pos)<(smallView?30:17))pos=p+(smallView?30:17);pos=Math.min(88,pos);used[col].push(pos);if(h!==null)leaders.push(`<line x1="49" y1="${y}" x2="${col===0?27:78}" y2="${pos}"/><circle cx="49" cy="${y}" r=".6"/>`);return `<button class="d2-marker" data-pick="${esc(q.key)}" style="--x:${col===0?27:78}%;--y:${pos}%" data-hot="${h>=80}" aria-pressed="${q.key===selected}" aria-label="${esc(name(q.team))} ${signed(q.line)}. ${esc(sys(q.system).name)}. ${h===null?'No settled record':h.toFixed(1)+' percent historical covers'}. ${state(q)}">${logo(q.team)}<span><b>${esc(abbr(q.team))} ${signed(q.line)}</b><small>${h===null?'Awaiting record':h.toFixed(1)+'% history'}</small><small>${q.g.done?'Final':q.g.live?'Live':time(q.g.date)<=Date.now()?'Started':'Pregame'}</small></span></button>`;}).join('');root.querySelector('#d2Markers').innerHTML=markup;root.querySelector('#d2Leaders').innerHTML=leaders.join('');root.querySelector('#d2AllTitle').textContent=`All ${choices.length} qualifying teams`;root.querySelector('#d2AllPicks').innerHTML=choices.map(q=>`<button data-pick="${esc(q.key)}" aria-pressed="${q.key===selected}">${logo(q.team)}<span><b>${esc(name(q.team))} ${signed(q.line)}</b><small>${esc(sys(q.system).name)} · ${state(q)}</small></span></button>`).join('');const empty=root.querySelector('#d2StageEmpty');empty.hidden=!!choices.length;empty.textContent=!fresh&&scope!=='results'?'Fresh data is needed before showing new qualifying games.':scope==='upcoming'?'No upcoming game with available data meets this system. No selection is being forced.':'No qualifying games in this view. Try another system or date.';const value=active?heat(active):null;root.querySelector('#d2Readout').innerHTML=`<strong>${value===null?'—':value.toFixed(1)+'%'}</strong><small>${lens==='tracked'?'covers since launch':lens==='prior'?'2023–25 covers':'2026 covers'}</small>`;scene?.setLevel(value===null?.08:value/100);
renderDetail(active,groups.get(active?.g.id+':'+active?.team)||[],focus);renderLedger(active?.system||system);}
